  `change_percentage` decimal(10,2) DEFAULT NULL,
  `severity` varchar(10) DEFAULT NULL,
  `message` varchar(255) DEFAULT NULL,
  `detected_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`event_id`),
  KEY `station_id` (`station_id`),
  KEY `reading_id` (`reading_id`),
  CONSTRAINT `pollution_events_ibfk_1` FOREIGN KEY (`station_id`) REFERENCES `stations` (`station_id`),
  CONSTRAINT `pollution_events_ibfk_2` FOREIGN KEY (`reading_id`) REFERENCES `aqi_readings` (`reading_id`)
) ENGINE=InnoDB AUTO_INCREMENT=228 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
